<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { request, errorText, date } from '../api';
import { session } from '../session';
import type { Node, Page } from '../types';
const data=ref<Page<Node>>({items:[],nextPageToken:''});const busy=ref(false);const error=ref('');const cursor=ref('');const history=ref<string[]>([]);const selected=ref<Node>();const drawer=ref(false);const adopting=ref<Node>();const allowExisting=ref(false);const adoptBusy=ref(false);
let active=new AbortController();
const online=computed(()=>data.value.items.filter(n=>n.state==='RUNNING').length);
async function load(){active.abort();active=new AbortController();const signal=active.signal;busy.value=true;error.value='';try{const result=await request<Page<Node>>(`/nodes?pageSize=50&pageToken=${encodeURIComponent(cursor.value)}`,{signal});if(!signal.aborted)data.value=result;}catch(e){if(!signal.aborted)error.value=errorText(e);}finally{if(!signal.aborted)busy.value=false;}}
function next(){history.value.push(cursor.value);cursor.value=data.value.nextPageToken;void load();}function previous(){cursor.value=history.value.pop()||'';void load();}
async function details(node:Node){error.value='';try{selected.value=await request<Node>(`/nodes/${node.nodeId}`);drawer.value=true;}catch(e){error.value=errorText(e);}}
function showAdopt(node:Node){adopting.value=node;allowExisting.value=false;}
async function adopt(){if(!adopting.value)return;adoptBusy.value=true;error.value='';try{await request(`/nodes/${adopting.value.nodeId}/adopt`,{method:'POST',body:{expectedRevision:adopting.value.agentRevision,allowExisting:allowExisting.value}});adopting.value=undefined;await load();}catch(e){error.value=errorText(e);}finally{adoptBusy.value=false;}}
onMounted(load);onBeforeUnmount(()=>active.abort());
</script>
<template><section class="sdn-page"><div class="page-head"><div><h1>节点管理</h1><p class="subtitle">查看节点身份、管理连接与配置能力，显式确认节点纳管。</p></div><el-button :loading="busy" @click="load">刷新节点</el-button></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><div class="summary-grid"><div class="metric"><div class="label">当前页节点</div><div class="value">{{data.items.length}}</div></div><div class="metric"><div class="label">管理连接 RUNNING</div><div class="value">{{online}}</div></div><div class="metric"><div class="label">当前页已纳管</div><div class="value">{{data.items.filter(n=>n.adopted).length}}</div></div></div><div class="panel"><el-table v-loading="busy" :data="data.items" row-key="nodeId" empty-text="尚无节点注册"><el-table-column label="节点" min-width="200"><template #default="{row}"><strong>{{row.name||row.endpoint}}</strong><div class="mono muted">{{row.nodeId}}</div></template></el-table-column><el-table-column prop="role" label="角色" width="100"/><el-table-column label="连接" width="120"><template #default="{row}"><el-tag :type="row.state==='RUNNING'?'success':row.state==='DOWN'?'danger':'info'">{{row.state}}</el-tag></template></el-table-column><el-table-column label="纳管" width="110"><template #default="{row}">{{row.adopted?'已纳管':'待确认'}}</template></el-table-column><el-table-column prop="agentRevision" label="Agent 版本" width="115"/><el-table-column label="最近心跳" min-width="170"><template #default="{row}">{{date(row.lastSeenUnixMs)}}</template></el-table-column><el-table-column label="操作" width="145"><template #default="{row}"><el-button link type="primary" @click="details(row)">详情</el-button><el-button v-if="session.role==='admin'&&!row.adopted" link type="primary" @click="showAdopt(row)">纳管</el-button></template></el-table-column></el-table><div class="pagination"><el-button :disabled="!history.length||busy" @click="previous">上一页</el-button><span class="muted">第 {{history.length+1}} 页 · 每页最多 50 个节点</span><el-button :disabled="!data.nextPageToken||busy" @click="next">下一页</el-button></div></div><el-drawer v-model="drawer" title="节点详情" size="60%"><template v-if="selected"><p class="mono">{{selected.nodeId}}</p><p class="subtitle">Endpoint：{{selected.endpoint}} · Instance：{{selected.instanceId}}</p><el-alert v-if="selected.observationError" :title="selected.observationError" type="warning"/><h2 style="margin:20px 0">操作能力</h2><el-table :data="selected.capabilities?.operations||[]"><el-table-column prop="code" label="操作"/><el-table-column label="后端"><template #default="{row}">{{row.backends.join(', ')}}</template></el-table-column><el-table-column label="支持回滚"><template #default="{row}">{{row.rollback?'是':'否'}}</template></el-table-column></el-table><h2 style="margin:20px 0">查询能力</h2><el-table :data="selected.capabilities?.queries||[]" empty-text="此 Agent 尚未声明查询能力"><el-table-column prop="kind" label="查询"/><el-table-column label="地址族"><template #default="{row}">{{row.families?.join(', ')}}</template></el-table-column><el-table-column label="OSPF 版本"><template #default="{row}">{{row.ospfVersions?.join(', ')}}</template></el-table-column></el-table><p class="subtitle">扩展：{{selected.capabilities?.features?.join(', ')||'无'}}</p><pre class="code">{{JSON.stringify(selected,null,2)}}</pre></template></el-drawer><el-dialog :model-value="!!adopting" title="确认节点纳管" width="560px" @close="adopting=undefined"><p>节点：{{adopting?.endpoint}}</p><p class="subtitle">读取并核对 Agent 当前版本 {{adopting?.agentRevision}}，建立 Controller 的管理基线。</p><el-checkbox v-model="allowExisting">允许接管已有配置（已核对该节点）</el-checkbox><template #footer><el-button @click="adopting=undefined">取消</el-button><el-button type="primary" :loading="adoptBusy" @click="adopt">确认纳管</el-button></template></el-dialog></section></template>
